<template>
  <div class="page-container offline-page">
    <div class="page-head"><div><h2>离线填报同步中心</h2><p>集中管理移动端离线保存记录，完成校验、重试和联网同步。</p></div><el-button type="primary" :disabled="!selectedIds.length" @click="syncSelected">同步选中记录（{{ selectedIds.length }}）</el-button></div>
    <div class="stat-grid"><div class="stat warning"><span>待同步</span><b>{{ countBy('待同步') }}</b></div><div class="stat success"><span>已同步</span><b>{{ countBy('已同步') }}</b></div><div class="stat danger"><span>校验异常</span><b>{{ countBy('校验异常') }}</b></div><div class="stat"><span>离线记录总数</span><b>{{ rows.length }}</b></div></div>
    <div class="panel"><el-form :inline="true" class="filters"><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="主体/区域/记录编号"/></el-form-item><el-form-item label="同步状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:140px"><el-option v-for="item in statuses" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form><el-table :data="rows" stripe @selection-change="selectionChange"><el-table-column type="selection" width="48" :selectable="selectable"/><el-table-column prop="id" label="记录编号" width="140"/><el-table-column prop="subjectName" label="填报主体" min-width="190"/><el-table-column prop="regionName" label="所属区域" width="105"/><el-table-column prop="cropName" label="作物" width="80"/><el-table-column prop="area" label="面积（亩）" width="100"/><el-table-column prop="savedAt" label="离线保存时间" width="155"/><el-table-column prop="device" label="采集终端" width="145"/><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag :type="tagType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">详情</el-button><el-button link type="warning" :disabled="!canRetry(row)" @click="retry(row)">{{ row.status === '校验异常' ? '校验并重试' : '重试' }}</el-button><el-button link type="success" :disabled="!canSync(row)" @click="syncOne(row)">同步</el-button></template></el-table-column></el-table></div>
    <el-dialog v-model="detailVisible" title="离线填报详情" width="600px"><template v-if="detail"><el-descriptions :column="2" border><el-descriptions-item label="记录编号">{{ detail.id }}</el-descriptions-item><el-descriptions-item label="同步状态"><el-tag :type="tagType(detail.status)">{{ detail.status }}</el-tag></el-descriptions-item><el-descriptions-item label="填报主体">{{ detail.subjectName }}</el-descriptions-item><el-descriptions-item label="所属区域">{{ detail.regionName }}</el-descriptions-item><el-descriptions-item label="作物">{{ detail.cropName }}</el-descriptions-item><el-descriptions-item label="面积">{{ detail.area }} 亩</el-descriptions-item><el-descriptions-item label="播种日期">{{ detail.sowDate }}</el-descriptions-item><el-descriptions-item label="采集终端">{{ detail.device }}</el-descriptions-item><el-descriptions-item label="保存时间" :span="2">{{ detail.savedAt }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ detail.remark || '无' }}</el-descriptions-item></el-descriptions></template><template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="detail && detail.status === '校验异常'" type="primary" @click="retry(detail)">校验并重试</el-button></template></el-dialog>
  </div>
</template>
<script setup>
import {
  onMounted,
  reactive,
  ref
} from 'vue'
import { ElMessage } from 'element-plus'
import { fetchOfflineReports, syncOfflineReports, updateOfflineReport, validateOfflineReport } from '@/api/gpm'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const selectedIds = ref([]); const detail = ref(null); const detailVisible = ref(false)
const statuses = ['待同步', '已同步', '校验异常']; const filters = reactive({ keyword: '', status: '' }); const busyIds = ref([])
const load = async () => { rows.value = await fetchOfflineReports(userStore.role, filters); selectedIds.value = selectedIds.value.filter(id => rows.value.some(item => item.id === id && selectable(item))) }
const countBy = status => rows.value.filter(item => item.status === status).length
const tagType = status => status === '已同步' ? 'success' : status === '校验异常' ? 'danger' : 'warning'
const isBusy = row => busyIds.value.includes(row.id); const canRetry = row => row.status === '校验异常' && !isBusy(row); const canSync = row => row.status === '待同步' && !isBusy(row)
const selectable = row => row.status === '待同步' && !isBusy(row); const selectionChange = list => { selectedIds.value = list.map(item => item.id) }
const reset = () => { Object.assign(filters, { keyword: '', status: '' }); load() }
const showDetail = row => { detail.value = row; detailVisible.value = true }
const retry = async row => { if (!canRetry(row)) return ElMessage.warning(row.status === '已同步' ? '已同步记录无需重试' : '请先完成校验'); busyIds.value.push(row.id); try { const result = await validateOfflineReport(row.id, userStore.role); if (result.success) { ElMessage.success('校验通过，记录已进入待同步状态'); await load(); if (detail.value?.id === row.id) detail.value = rows.value.find(item => item.id === row.id) } else { await updateOfflineReport(row.id, { status: '校验异常', validateMessage: result.message }); ElMessage.error(result.message || '校验失败'); await load() } } finally { busyIds.value = busyIds.value.filter(id => id !== row.id) } }
const syncOne = async row => { if (!canSync(row)) return ElMessage.warning(row.status === '校验异常' ? '校验异常记录禁止直接同步，请先校验并重试' : '当前记录不可同步'); busyIds.value.push(row.id); try { const result = await syncOfflineReports([row.id], userStore.regionName); if (result.success) { ElMessage.success('记录同步成功'); await load() } else ElMessage.error(result.message || '同步失败') } finally { busyIds.value = busyIds.value.filter(id => id !== row.id) } }
const syncSelected = async () => { const ids = selectedIds.value.filter(id => rows.value.some(item => item.id === id && item.status === '待同步')); if (!ids.length) return ElMessage.warning('请选择待同步记录，校验异常记录禁止直接同步'); busyIds.value.push(...ids); try { const result = await syncOfflineReports(ids, userStore.regionName); if (result.success) { ElMessage.success(`已同步 ${result.count} 条记录`); selectedIds.value = []; await load() } else ElMessage.error(result.message || '同步失败') } finally { busyIds.value = busyIds.value.filter(id => !ids.includes(id)) } }
onMounted(load)
</script>
<style lang="scss" scoped>
.offline-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.eyebrow{color:var(--ah-primary);font-size:11px;letter-spacing:1px;font-weight:700}h2{margin:4px 0;font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{background:#fff;border-radius:8px;padding:14px 18px;border-left:4px solid var(--ah-primary);box-shadow:0 1px 4px rgba(15,62,120,.06)}.stat.warning{border-color:var(--ah-warning)}.stat.success{border-color:var(--ah-success)}.stat.danger{border-color:var(--ah-danger)}.stat span{display:block;color:var(--ah-text-secondary);font-size:12px}.stat b{display:block;font-size:24px;margin-top:5px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px;margin-right:12px}@media(max-width:900px){.stat-grid{grid-template-columns:repeat(2,1fr)}}
</style>
